"""Weak, signed guess for component p-82af68dd@100000/layers.15.mlp.down_proj:1357.

What the component does: it writes a small vector into the residual stream whose
unembedding favours words such as "other", "else" and "otherwise". Its own activation is
a diffuse signed value with a standard deviation of about 0.3, and almost none of it is
explained by the current word. The few word classes below carry consistent average
signs, so the program predicts those averages and 0 elsewhere:

- chat-turn boundary tokens (end of a turn, end of a thought): clearly positive;
- chat-turn start and thought-open tokens: clearly negative;
- contrast and coordination words: "but", "or", "however", "whereas" positive;
  "while", "although", "only", "instead" negative;
- a few punctuation and marker tokens ("by", "?", "__") negative.

It explains well under 1% of the activation's variance, so it is a description of the
average sign, not of the component's behaviour.
"""

READS = ()

CHAT_END = {"<|im_end|>", "</think>"}
CHAT_START = {"<|im_start|>", "<think>"}
CONTRAST_POS = {" but", " or", " However", " however", " whereas"}
CONTRAST_NEG = {" while", " While", " although", " Although", " only", " instead"}
MISC_NEG = {" by", "?", "__"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CHAT_END:
        return carry, 0.35
    if token in CHAT_START:
        return carry, -0.2
    if token in CONTRAST_POS:
        return carry, 0.2
    if token in CONTRAST_NEG:
        return carry, -0.12
    if token in MISC_NEG:
        return carry, -0.14
    return carry, 0.0

"""Layer-15 MLP hidden unit 1358 (about two-thirds of the component's input), by word role.

The unit reads the current token and the one before it; it does not track longer context.
- Strongly negative (-1.0) on past participles of verbs of making, providing and specifying
  ("created", "provided", "defined", "generated", "specified", "produced", ...).
- Negative (-1.0) on any other -ed participle right after "as" ("as specified", "as defined"),
  and mildly negative (-0.2) on an -ed participle right after a noun ("data generated").
- Mildly positive (+0.3) on "on", "upon", "onto", "into", "about", "against"; weakly (+0.1) on
  "of", "to", "for".
- Positive (+0.7) on recipient verbs ("named", "appointed", "awarded", "handed", "told",
  "sent", "given").
- Everything else is 0.
The word lists are the content. Most of the unit's variance is not captured by any word or
word-class rule: token identity alone explains about 2% out of sample, so this predicts
only a small part of the activation.
"""
import re

import wordnet

MAKING_PARTICIPLES = {
    "created", "provided", "defined", "generated", "specified", "produced", "obtained",
    "developed", "requested", "discussed", "mentioned", "presented", "formed", "imposed",
    "taught", "described", "shown", "offered", "outlined", "calculated", "required",
    "manufactured", "established", "identified", "introduced", "proposed", "determined",
}
STRONG_PREPOSITIONS = {"on", "upon", "onto", "into", "about", "against"}
WEAK_PREPOSITIONS = {"of", "to", "for"}
RECIPIENT_VERBS = {"named", "appointed", "awarded", "handed", "told", "sent", "given"}
AUXILIARIES = {"was", "were", "been", "being", "is", "are", "be", "got", "get"}
READS = ()


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    value = 0.0
    if cur in MAKING_PARTICIPLES:
        value = -1.0
    elif re.fullmatch(r"[a-z]{3,}ed", cur):
        if prev == "as":
            value = -1.0
        elif prev.isalpha() and prev not in AUXILIARIES and "noun" in wordnet.parts_of_speech(prev):
            value = -0.2
    elif cur in STRONG_PREPOSITIONS:
        value = 0.3
    elif cur in WEAK_PREPOSITIONS:
        value = 0.1
    elif cur in RECIPIENT_VERBS:
        value = 0.7
    return carry, value

"""Purpose-clause detector.

This component fires on the words that open a purpose clause: the "to" (or "in order to",
"so that", "чтобы") that says why an action is done, and the verb or noun that states the goal.
It is strongest on the verb right after a purpose "to" ("tools to [make]", "used to [get]",
"to [ensure]"), on "order" in "in order", and on purpose connectives in other languages
("чтобы", "afin", "以便", "aby", "để"). Elsewhere it is near zero, with a small negative
background that is not modelled here.

Inside "to + verb", the verb matters: goal verbs (ensure, confirm, help, make, get...) fire
strongly, while state and attitude verbs (be, have, remain, believe, love...) fire weakly. After a
complement word (likely to, seems to, able to, according to) "to" marks a complement, not a goal,
so it fires weakly.
"""

from wordnet import parts_of_speech

READS = ()

PURPOSE_WORDS = {"чтобы": 8.0, "afin": 8.5, "aby": 6.0, "để": 6.5, "以便": 12.0, "为了": 4.0, "从而": 4.0}

GOAL_VERBS = {
    "make", "get", "ensure", "confirm", "verify", "illustrate", "demonstrate", "help", "assist",
    "guide", "determine", "obtain", "facilitate", "resolve", "show", "allow", "indicate",
    "estimate", "test", "locate", "achieve", "protect", "prevent", "avoid", "solve", "improve",
    "reduce", "assess", "measure", "maintain", "see", "keep", "form", "finance", "celebrate",
}

STATE_VERBS = {"be", "have", "become", "remain", "believe", "love", "consider", "ignore",
               "mention", "lose", "seem", "appear"}

COMPLEMENT_WORDS = {
    "seem", "seems", "seemed", "appear", "appears", "likely", "unlikely", "tend", "tends",
    "able", "unable", "ought", "according", "compared", "similar", "due", "related", "respect",
    "pursuant", "equal", "prior", "need", "needed", "needs", "want", "wanted", "have", "has",
    "had", "going", "try", "tried", "return", "returning", "new", "safe", "change", "changes",
}

FUNCTION_WORDS = {"the", "a", "an", "this", "that", "these", "those", "his", "her", "its",
                  "their", "your", "my", "our", "me", "you", "him", "them", "us", "it", "any",
                  "all", "some", "many", "more", "each", "example", "instance"}


def _word(text):
    return text.strip().lower()


def _is_verb(word):
    return word.isalpha() and "verb" in parts_of_speech(word)


def step(carry, prefix, upstream):
    toks, docs = prefix.token_strings, prefix.document_ids
    n = len(docs)

    def back(k):
        # the word k tokens back, if it is in the same document
        if n > k and docs[-1 - k] == docs[-1]:
            return _word(toks[-1 - k])
        return ""

    cur, p1, p2 = _word(toks[-1]), back(1), back(2)
    if p1 == "to" and _is_verb(cur):
        if p2 in COMPLEMENT_WORDS:
            value = 2.0
        elif cur in GOAL_VERBS:
            value = 9.0
        elif cur in STATE_VERBS:
            value = 1.5
        else:
            value = 4.7
    elif cur in PURPOSE_WORDS:
        value = PURPOSE_WORDS[cur]
    elif cur == "order" and p1 == "in":
        value = 9.0
    elif cur == "to" and p1 == "order":
        value = 7.4
    elif cur == "that" and p1 == "so":
        value = 3.6
    elif p1 == "for" and cur in ("a", "an"):
        value = 2.4
    elif p1 == "for" and cur.isalpha() and cur not in FUNCTION_WORDS:
        value = 1.5
    else:
        value = 0.0
    return carry, value

"""Division detector for layers.15 mlp.down_proj component 1368.

The component reads the division operator of a mathematical expression. It is near
zero on most tokens and switches on at the token where a division happens:

- a slash ("/" or " /") right after a number, a variable or a closing bracket, as in
  "1/2", "x/y", "(a+b)/c";
- a bracket followed by a slash (")/", "))/", "]/") or a LaTeX fraction joint "}{";
- in LaTeX \\frac{...}{...}: the "{" that opens the denominator, and its first digit;
- the word "per", "divided by" and "mod" as division words.

Strength: a bracket before the slash, or a LaTeX fraction joint, is strongest; a slash
after a one-digit numerator ("1/2") is strong, more so in an equation; a slash after a
longer number (often a date or ratio like "10/12") is weaker; a slash after a variable
is medium. Slashes in paths, URLs and ordinary words stay near zero.
Predicted values are typical activations measured on training text, not fitted per token.
"""

READS = ()

BRACKET_DIVISION = {")/", ")/(", "))/", "]/", "/("}
DIVISION_WORDS = {" per": 2.9, " divided": 5.7, " mod": 2.6}
MATH_MARKS = ("=", "(", "+", "*", "^", "\\", "$")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    nearby = "".join(toks[-12:-1])
    in_math = any(m in nearby for m in MATH_MARKS)
    in_frac = "frac" in nearby

    if tok in BRACKET_DIVISION:
        value = 30.0
    elif tok == "}{":
        value = 35.0 if in_frac else 3.0  # fraction joint, or a brace in other code
    elif tok == "{" and prev.endswith("}") and in_frac:
        value = 35.0  # opens the denominator of a LaTeX fraction
    elif tok.isdigit() and prev in ("{", "}{") and in_frac:
        value = 5.0  # first digit of the denominator
    elif tok == " by" and prev == " divided":
        value = 28.0
    elif tok in ("/", " /"):
        if prev.isdigit() and not prev2.isdigit():
            value = 24.0 if in_math else 13.0  # one-digit numerator
        elif prev.isdigit():
            value = 9.0  # longer number: date, ratio or fraction
        elif prev.endswith((")", "]", "}")):
            value = 29.0  # bracket before the slash
        elif len(prev.strip()) == 1 and prev.strip().isalpha():
            value = 10.0  # single-letter variable: x/y
        else:
            value = 2.7  # path, URL or word
    else:
        value = DIVISION_WORDS.get(tok, 0.0)
    return carry, value

"""Layer 15 MLP down_proj, component 1371: a near-null direction with only a faint token-class tilt.

The component's activation is dense and roughly symmetric around zero (std 0.29), and it is
essentially never important to the model: switching it off changes next-token predictions by
about 1e-6 nats per position. No simple rule predicts its size. The one readable tendency we
found is by token class: digits lean slightly positive, bare whitespace slightly positive,
and punctuation and ordinary words slightly negative. Those class means explain well under 1%
of its variance, so this program is mostly a predictor of ~0.

Class means were fit on training rows (about 4M tokens; the held-out R^2 is about 0.3%).
"""

READS = ()

MEAN_BY_CLASS = {"digit": 0.038, "space": 0.021, "other": 0.006, "punct": -0.017, "word": -0.010}


def token_class(text):
    if text.strip() == "":
        return "space"
    if text.isdigit():
        return "digit"
    if all(not ch.isalnum() for ch in text):
        return "punct"
    if text.isalpha():
        return "word"
    return "other"


def step(carry, prefix, upstream):
    return carry, MEAN_BY_CLASS[token_class(prefix.token_strings[-1])]

"""Layer 15, MLP hidden unit 1372, read through its down_proj component.

The component reads almost only this one hidden unit (its input direction is 0.82 unit 1372,
the rest spread thin), so its activation is close to that unit's value. The activation is mostly
negative, and its large negative values (where the component matters) come on linking tokens:
copulas and auxiliaries (is, was, has, can), possessive 's, Japanese case particles
(を の に が は と), dashes and arithmetic or code operators (- — / * + -> ^ ==), the double
underscore "__" in identifiers and paths, and method dots (.get, .split). It rises on place
names (countries and US states). Other tokens sit near zero.

The program predicts each group's average activation. On eval rows it explains about 3% of the
variance (r = 0.18). The unit also depends on context the token alone does not show, which
this program leaves out.
"""

import pycountry

READS = ()

PLACES = {c.name.lower() for c in pycountry.countries} | {
    s.name.lower() for s in pycountry.subdivisions if s.country_code == "US"
}
COPULAS = set("is was are were be been being has have had can will would could should may might must does did".split())
PARTICLES = set("を の に が は と で も へ や".split())
OPERATORS = {"-", "—", "–", "/", "*", "+", "->", "^", "×", "==", "!=", "::", ")^", ")/", "*("}
MEAN = {"under": -1.8, "possessive": -1.1, "particle": -0.8, "operator": -0.5,
        "copula": -0.4, "method": -0.1, "place": 0.6}


def group(token):
    """The linking-token group a token belongs to, or None."""
    w = token.strip()
    if w == "__":
        return "under"
    if w in ("'s", "’s"):
        return "possessive"
    if w in PARTICLES:
        return "particle"
    if w.lower() in COPULAS:
        return "copula"
    if w in OPERATORS:
        return "operator"
    if w.startswith(".") and w[1:].isalpha():
        return "method"
    if w.lower() in PLACES:
        return "place"
    return None


def step(carry, prefix, upstream):
    # Each document starts fresh: its first token sits at zero.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    return carry, MEAN.get(group(prefix.token_strings[-1]), 0.0)

"""Layer 15 MLP down_proj, component 1374: a possessive-word detector.

What it does: it is positive on possessive words (his, her, its, their, my, your, our,
and 's) that open a noun phrase, most strongly when the possessive follows a preposition
("in his", "by her", "from their"). It is negative on reflexive pronouns (himself,
themselves, yourself), on object pronouns after a preposition or verb ("to you",
"for me", "help them"), and on "own". Everything else gets 0.

Why: this is a rough, word-level rule read off the component's activations. Its output
direction, read through the unembedding, promotes reflexive pronouns (yourselves,
themselves, himself) when the activation is positive. But the model's own predicted
probability of a reflexive next token does not track the activation, so the reason
possessives drive it is not established here.

It explains about 8% of the variance. Most of the activation is spread thinly over many
tokens and is not captured by any simple word rule.
"""

from collections.abc import Mapping

READS = ()

POSSESSIVE = {"his", "her", "its", "their", "my", "your", "our", "'s", "’s"}
REFLEXIVE = {"himself", "herself", "themselves", "yourself", "myself", "ourselves"}
REFLEXIVE |= {"itself", "oneself", "yourselves"}
OBJECT_PRONOUN = {"me", "you", "him", "us", "them"}
PREPOSITION = {"in", "by", "from", "to", "on", "of", "at", "into", "with", "for", "through", "about"}
VERB_OR_PREP = PREPOSITION | {"help", "give", "tell", "told", "see", "than"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in POSSESSIVE:
        value = 3.4 if prev in PREPOSITION else 1.8
    elif word in REFLEXIVE:
        value = -2.2
    elif word in OBJECT_PRONOUN and prev in VERB_OR_PREP:
        value = -1.1
    elif word == "own":
        value = -0.9
    else:
        value = 0.0
    return carry, float(value)

"""Word-class program for p-82af68dd@100000/layers.15.mlp.down_proj:1376.

This component is a dense, high-frequency feature. Its activation is mostly not
predictable from the current word, its neighbours, its position or any readable
word class: the best readable predictors reach under 1% of the variance. The
concepts below are the ones with a consistent sign and mean, so the program is
a per-class average of the activation:

- nationality adjectives ("Irish", "American", "German", ...): clearly positive
  (mean about +2);
- relational adjectives, WordNet's pertainyms ("medical", "bacterial",
  "territorial"): mildly positive (mean about +0.4);
- nouns (WordNet, not verbs): slightly positive (about +0.06);
- adverbs and verbs: slightly negative (about -0.04);
- everything else (punctuation, numbers, code, whitespace, other words): about 0.
"""

import wordnet

READS = ()

NATIONALITY_ADJECTIVES = frozenset(
    """Irish Italian Canadian Polish Indian Australian British Brazilian Scottish
    Russian French Japanese American Dutch Spanish German Chinese Jewish Swedish
    Norwegian Danish Finnish Greek Turkish Mexican Korean Egyptian Israeli Iranian
    Iraqi Pakistani Filipino Vietnamese Thai Hungarian Czech Austrian Swiss Belgian
    Portuguese Argentine Chilean Peruvian Cuban Nigerian Kenyan Ukrainian Romanian
    Bulgarian Serbian Croatian Syrian Saudi""".split()
)
MEAN = {"nationality": 2.0, "pertainym": 0.4, "noun": 0.06, "adverb": -0.045, "verb": -0.036}


def word_class(token):
    word = token.strip()
    if word in NATIONALITY_ADJECTIVES:
        return "nationality"
    if not (word.isascii() and word.isalpha()):
        return "other"
    word = word.lower()
    parts = wordnet.parts_of_speech(word)
    if "adjective" in parts and "adj.pert" in wordnet.categories(word):
        return "pertainym"
    if "noun" in parts and "verb" not in parts:
        return "noun"
    if parts == {"adverb"}:
        return "adverb"
    if "verb" in parts and "noun" not in parts:
        return "verb"
    return "other"


def step(carry, prefix, upstream):
    return carry, MEAN.get(word_class(prefix.token_strings[-1]), 0.0)

"""Layer 15 MLP unit 1400 (down_proj), read as a feature of the text so far.

It goes negative where a new object is being set up. The strongest case is a verb of making,
providing or obtaining things ("create", "provide", "produce", "obtain", "generate", "offer",
"contain") in its base, -s or -ing form, and the same in Chinese ("提供", "构建", "创建").
The determiner or quantifier that opens that object ("a", "an", "some", "any", "several",
"two", "many", "the", and Chinese "一个", "一些") is negative too: most after such a verb,
after be/have ("is a", "has a") or after a preposition, less after another word, and hardly at
all after punctuation, a number or the start of a document. "of" after a collection or making
noun ("a series of", "a variety of", "consists of") is strongly negative too. Its sign promotes
adjectives in the next-token readout ("interesting", "reliable", "famous"): a modifier is
coming. Elsewhere it predicts 0.
"""

import re
from collections.abc import Mapping
from functools import lru_cache

import wordnet

READS: tuple[str, ...] = ()

# Each determiner's value on its own.
DETERMINER = {
    "a": -2.2, "an": -2.2, "any": -2.2, "some": -1.8, "several": -2.4,
    "another": -1.3, "two": -1.5, "many": -1.0, "other": -1.1, "these": -0.3,
    "the": 0.2, "this": 0.5,
}
# The same, in Chinese: quantifiers and measure words, and verbs of making or providing.
DETERMINER_ZH = {
    "一个": -6.0, "一些": -6.0, "一种": -4.0, "许多": -4.0, "很多": -2.5, "两个": -2.8,
    "任何": -3.6, "这些": -2.5, "那些": -3.2, "某些": -3.0, "各种": -3.0, "更多": -3.0,
    "个": -2.8, "种": -2.4,
}
MAKE_VERBS_ZH = {"提供", "构建", "建立", "创建", "生成", "产生", "获取", "形成", "包含", "拥有", "采用"}
PREPOSITION = {"of": -0.8, "with": -1.0, "into": -0.9, "via": -0.6, "as": -0.5}
PREPOSITIONS = {
    "of", "with", "to", "for", "from", "by", "into", "in", "on", "at", "as", "about",
    "through", "over", "under", "within", "during", "among", "via", "across", "against",
    "between",
}
BE_HAVE = {"is", "are", "was", "were", "be", "been", "being", "am", "has", "have", "had"}
# Verbs of making, providing or obtaining a thing.
MAKE_VERBS = {
    "create", "provide", "produce", "generate", "obtain", "offer", "develop", "contain",
    "build", "construct", "establish", "acquire", "receive", "buy", "issue", "release",
    "present", "form", "design", "write", "include",
}
# Nouns and verbs of collecting or making, which an "of" object follows.
COLLECTION_OF = {
    "series", "variety", "set", "pair", "bunch", "collection", "list", "group", "family", "team",
    "network", "host", "handful", "plurality", "array", "selection", "thousands", "number", "range",
    "lot", "amount", "combination", "mix", "presence", "existence", "availability", "occurrence",
    "production", "creation", "formation", "synthesis", "preparation", "generation", "introduction",
    "establishment", "addition", "acquisition", "delivery", "identification", "discovery",
    "accumulation", "consists", "consisted", "consist", "composed", "comprised", "comprises",
}
SHIFT = {"be_have": -2.4, "make": -2.6, "verb": -2.0, "preposition": -1.7, "word": -0.6}
VERB_VALUE = -3.0  # on a making verb itself


@lru_cache(None)
def lemma(word: str) -> str:
    """The base form WordNet gives a word, or the word itself."""
    forms = wordnet.base_forms(word)
    return forms[0] if forms else word


@lru_cache(None)
def is_verb(word: str) -> bool:
    """Whether WordNet lists the word, in any inflected form, as a verb."""
    if "verb" in wordnet.parts_of_speech(word):
        return True
    return any("verb" in wordnet.parts_of_speech(base) for base in wordnet.base_forms(word))


def is_making_verb(word: str) -> bool:
    """A making verb in its base, -s or -ing form: 'provide', 'provides', 'providing'."""
    base = lemma(word)
    return base in MAKE_VERBS and word in (base, base + "s", base + "ing", base[:-1] + "ing")


def shift(before: str) -> float:
    """How the previous word moves a determiner's value."""
    if not before.isalpha():  # punctuation, a number, or the start of a document
        return 0.0
    if before in BE_HAVE:
        return SHIFT["be_have"]
    if before in PREPOSITIONS:
        return SHIFT["preposition"]
    if before in MAKE_VERBS_ZH or is_making_verb(before) or lemma(before) in MAKE_VERBS:
        return SHIFT["make"]
    if is_verb(before):
        return SHIFT["verb"]
    return SHIFT["word"]


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    else:
        before = prefix.token_strings[-2].strip().lower()
    if word in DETERMINER:
        return carry, DETERMINER[word] + shift(before)
    if word in DETERMINER_ZH:
        return carry, DETERMINER_ZH[word] + shift(before)
    if word in MAKE_VERBS_ZH:
        return carry, VERB_VALUE
    if word == "of" and before in COLLECTION_OF:
        return carry, -5.0
    if word in PREPOSITION:
        return carry, PREPOSITION[word]
    if word.isalpha() and is_making_verb(word):
        return carry, VERB_VALUE
    return carry, 0.0

"""Layer 15 MLP hidden unit 1407 (this component's activation), as a word-level rule.

The unit reads the word that opens a condition, a requirement or an exclusion, and it
responds most when the sentence is saying what must hold or what is left out:

- Exclusion words get the strongest response: "without", "unless" (and "sans", "senza",
  "ohne", "без", "没有", "除非").
- Requirement and restriction words get a moderate one: "must", "requires", "need",
  "should", "until", "only", "except" (and "必须", "只有").
- Negation words get a weak response on their own ("not", "n't", "no", "不", "没").
- Negation right after a condition ("if you are not", "unless it's not", "如果不") gets a
  stronger one.
- The word after a necessity word ("have to", "need to", "failure to", "must be",
  "should be") gets a moderate one.

Every other token sits slightly below zero (-0.05, the average there).
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

EXCLUSION = {" without", " Without", " unless", " Unless", " sans", " senza", " ohne",
             " без", " Без", "没有", "除非"}
REQUIREMENT = {" must", " requires", " require", " need", " needs", " should", " until",
               " Until", " only", " Only", " except", " lacking", "必须", "只有", "只能"}
NEGATION = {" not", "’t", "'t", " no", " cannot", " non", "不", "没", "未"}
CONDITION = {" if", "if", " unless", " when"}
CONDITIONAL_NEGATION = {"如果不", "如果没有", "如果沒有", "若不", "若没有"}
NECESSITY = {" need", " needs", " have", " has", " had", " got", " failure", " failing"}
MODAL = {" must", " should", " only"}


def step(carry, prefix, upstream: Mapping):
    tokens, docs = prefix.token_strings, prefix.document_ids
    cur = tokens[-1]

    def back(k):
        # the token k steps before the newest one, if it is in the same document
        i = len(tokens) - 1 - k
        return tokens[i] if i >= 0 and docs[i] == docs[-1] else ""

    if cur in EXCLUSION:
        return carry, 10.0
    if cur in REQUIREMENT:
        return carry, 3.0
    if cur in CONDITIONAL_NEGATION:
        return carry, 8.0
    if cur in NEGATION:
        if any(back(k) in CONDITION for k in (1, 2, 3)):
            return carry, 6.0
        return carry, 1.0
    if (cur in {" to", " be"}) and (back(1) in NECESSITY or back(1) in MODAL):
        return carry, 3.0
    return carry, -0.05
